import pandas as pd
from sqlalchemy import text

def audit(session):
    scalar=lambda q:session.execute(text(q)).scalar()
    return {"events":scalar("SELECT count(*) FROM high_impact_events"),"accepted":scalar("SELECT count(*) FROM high_impact_events WHERE status='accepted'"),"rejected":scalar("SELECT count(*) FROM high_impact_events WHERE status='rejected'"),"assets":scalar("SELECT count(*) FROM high_impact_event_assets"),"reactions":scalar("SELECT count(*) FROM high_impact_market_reactions"),"analyses_success":scalar("SELECT count(*) FROM high_impact_event_analysis WHERE status='success'"),"duplicate_url":scalar("SELECT count(*) FROM (SELECT url FROM high_impact_events GROUP BY url HAVING count(*)>1)x"),"duplicate_canonical":scalar("SELECT count(*) FROM (SELECT canonical_url FROM high_impact_events WHERE canonical_url IS NOT NULL GROUP BY canonical_url HAVING count(*)>1)x"),"duplicate_hash":scalar("SELECT count(*) FROM (SELECT content_hash FROM high_impact_events GROUP BY content_hash HAVING count(*)>1)x"),"duplicate_identity":scalar("SELECT count(*) FROM (SELECT platform,external_id FROM high_impact_events WHERE external_id IS NOT NULL GROUP BY platform,external_id HAVING count(*)>1)x"),"non_utc_timestamps":scalar("SELECT count(*) FROM high_impact_events WHERE published_at IS NULL"),"future_events":scalar("SELECT count(*) FROM high_impact_events WHERE published_at>now()"),"modified_before_published":scalar("SELECT count(*) FROM high_impact_events WHERE modified_at IS NOT NULL AND modified_at<published_at")}
